    # ---- B9 redone (review of 2026-10-19): no overlapping weeks
    L0, L1 = C.LL_BLOCKS[0], C.LL_BLOCKS[-1]
    chg = ll[ll["kind"] == "change"]
    def _llr(p, d, L):
        g = chg[(chg["pair"] == p) & (chg["direction"] == d) & (chg["block_weeks"] == L)]
        return g.iloc[0] if len(g) else None
    def _ok(r_):
        return r_ is not None and pd.notna(r_["nw_t"]) and abs(r_["nw_t"]) >= 2 and pd.notna(r_["pearson_nonoverlap"]) and np.sign(r_["pearson"]) == np.sign(r_["pearson_nonoverlap"])
    def _cell(p, d):
        a_, b_ = _llr(p, d, L0), _llr(p, d, L1)
        if a_ is None or b_ is None:
            return "—"
        same = np.sign(a_["pearson"]) == np.sign(b_["pearson"])
        unconf = [L for L, r_ in ((L0, a_), (L1, b_)) if pd.notna(r_["nw_t"]) and abs(r_["nw_t"]) >= 2 and pd.isna(r_["pearson_nonoverlap"])]
        tail = (" — reliable at both lengths" if _ok(a_) and _ok(b_) and same else (f" — reliable at {L0} wk only" if _ok(a_) and not _ok(b_) else (f" — reliable at {L1} wk only" if _ok(b_) and not _ok(a_) else (" — not reliable" if not (_ok(a_) or _ok(b_)) else " — the sign flips between the two lengths: not robust"))))
        if unconf:
            tail += f" (|t| ≥ 2 at {' and '.join(str(L) for L in unconf)} wk but too few non-overlapping blocks to confirm)"
        return f"{L0}-wk {a_['pearson']:+.2f} (t {a_['nw_t']:+.1f}), {L1}-wk {b_['pearson']:+.2f} (t {b_['nw_t']:+.1f})" + tail
    H.append(box("q", "Redone on 2026-10-19 with NO overlapping weeks.", f"The first version of this test (the two bar charts further down, kept for reference) related the 13-week change in volatility at week t to the 13-week change in correlation at week t + k. At k = 4 the two 13-week windows share 9 of their 13 weeks, so the two 'changes' are largely the same weeks measured twice — any apparent lead is contaminated. The redone test uses blocks that share nothing: X is measured on the block of L weeks ending at t (t−L+1 … t) and Y on the block of L weeks starting the week after (t+1 … t+L), for L = {L0} and L = {L1}. On each block: the pair's correlation over the block's weeks, the pair's own realised vol (each leg's standard deviation over the block, averaged, annualised), and the VIX's change over the block (log level at the end minus at the start). Then, for every pair, both directions — does this block's correlation change tell you the next block's volatility change (correlation → vol), and does this block's volatility change tell you the next block's correlation change (vol → correlation) — as changes (block minus the block before it; the chart) and as levels (the table), each with Pearson, Spearman, a Newey-West t (the blocks step weekly, so neighbours overlap and the t corrects for it) and the Pearson on the strictly non-overlapping sub-sample (every L-th week). A link is called reliable only if |t| ≥ 2 AND the non-overlapping sample agrees in sign."))
    H.append(_fig("5_lead_lag_blocks"))
    H.append(elements([("One panel per pair", "index pairs first, gold pairs last; all on one y-scale."),
                       ("The four bar positions", "corr → vol: the pair's correlation change this block against its own-vol change next block (a positive bar = coupling leads volatility). vol → corr: the pair's own-vol change this block against its correlation change next block (positive = volatility leads coupling). corr → VIX and VIX → corr: the same with the VIX's log change over the block."),
                       ("Dark vs light bars", f"{L0}-week blocks (dark) and {L1}-week blocks (light); the t above each bar is Newey-West; a bar outlined in red passed both reliability tests."),
                       ("Hover", "Pearson, t, Spearman, the non-overlapping Pearson and both sample sizes.")]))
    eqp_ = [p for p in pairs if "Gold" not in p and p in set(chg["pair"])]; gdp_ = [p for p in pairs if "Gold" in p and p in set(chg["pair"])]
    vx_rel = sum(1 for p in eqp_ for L in C.LL_BLOCKS if _ok(_llr(p, "VIX → correlation", L))); vx_n = sum(1 for p in eqp_ for L in C.LL_BLOCKS if _llr(p, "VIX → correlation", L) is not None)
